export * as Progress from './progress.tsx';
export type {
  RootOwnProps as ProgressRootOwnProps,
  RootProps as ProgressRootProps,
} from './progress.tsx';

import type * as React from 'react';

/** Fraction of the way from min to max, clamped to 0–1. `null` (indeterminate) stays null. */
export function fraction(value: number | null | undefined, min = 0, max = 100): number | null {
  if (value === null || value === undefined || Number.isNaN(value)) return null;
  const span = max - min;
  if (span <= 0) return 1;
  const f = (value - min) / span;
  return f < 0 ? 0 : f > 1 ? 1 : f;
}

/** Base UI's style prop: an object or a function of state. */
export type StyleProp<State> =
  | React.CSSProperties
  | ((state: State) => React.CSSProperties | undefined)
  | undefined;

/**
 * Merge declarations (CSS custom properties or overrides) under a Base UI style prop, keeping
 * its function form. The caller's own declarations win.
 */
export function withVars<State>(
  style: StyleProp<State>,
  vars: React.CSSProperties | Record<`--${string}`, string | number> | undefined,
): StyleProp<State> {
  if (!vars) return style;
  if (typeof style === 'function') {
    return (state: State): React.CSSProperties => ({
      ...(vars as React.CSSProperties),
      ...style(state),
    });
  }
  return { ...(vars as React.CSSProperties), ...style };
}

@layer hj.components {
  /* Customise: --hj-progress-height · --hj-progress-radius */
  .hj-progress {
    --_tone: var(--hj-accent);
    display: flex;
    flex-direction: column;
    gap: calc(8px * var(--hj-density));
    min-width: 0;
    width: 100%;
    font-family: var(--hj-font-sans);
  }
  .hj-progress[data-tone='fg'] {
    --_tone: var(--hj-fg);
  }
  .hj-progress[data-tone='danger'] {
    --_tone: var(--hj-danger);
  }

  .hj-progress-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: calc(12px * var(--hj-density));
  }
  .hj-progress-label {
    font-size: 13px;
    font-weight: 600;
    color: var(--hj-fg);
  }
  .hj-progress-value {
    font: var(--hj-type-mono);
    letter-spacing: var(--hj-tracking-mono);
    font-variant-numeric: tabular-nums;
    color: var(--hj-fg-dim);
  }

  .hj-progress-track {
    position: relative;
    overflow: hidden;
    height: var(--hj-progress-height, 4px);
    border-radius: var(--hj-progress-radius, var(--hj-radius-pill));
    background: color-mix(in srgb, var(--_tone) 22%, transparent);
  }

  /* Full width, scaled from the left: transform only, on the clamped snappy spring. */
  .hj-progress-indicator {
    position: absolute;
    inset: 0;
    border-radius: inherit;
    corner-shape: inherit;
    background: var(--_tone);
    transform-origin: left center;
    transform: scaleX(var(--hj-progress-fraction, 0));
    transition:
      transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle),
      background-color var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-progress-indicator:dir(rtl) {
    transform-origin: right center;
  }

  /* Indeterminate: a third of the track sweeps across. Paused (mid-track) under reduced motion. */
  .hj-progress-indicator[data-indeterminate] {
    transform: translateX(-34%) scaleX(0.333);
    animation: hj-progress-sweep 1400ms var(--hj-ease-out) infinite;
    animation-delay: -560ms;
    animation-play-state: var(--hj-ambient);
  }
  @keyframes hj-progress-sweep {
    from {
      transform: translateX(-34%) scaleX(0.333);
    }
    to {
      transform: translateX(100%) scaleX(0.333);
    }
  }
}

'use client';
import { Progress as Base } from '@base-ui/react/progress';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart, part } from '../../system/part.tsx';
import type { ElementPartProps, HanjiPart } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';
import { fraction, withVars } from './progress-math.ts';

export const Label: HanjiPart<typeof Base.Label> = part(
  Base.Label,
  'Progress.Label',
  'hj-progress-label',
);
export const Value: HanjiPart<typeof Base.Value> = part(
  Base.Value,
  'Progress.Value',
  'hj-progress-value',
);
export const Track: HanjiPart<typeof Base.Track> = part(
  Base.Track,
  'Progress.Track',
  'hj-progress-track',
);
/** Label on the left, value on the right, above the track. */
export const Header: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Progress.Header',
  'hj-progress-header',
);

export interface RootOwnProps {
  /** accent = the task in hand · fg = neutral totals · danger = something is running out. */
  tone?: 'accent' | 'fg' | 'danger';
}
export interface RootProps extends RootOwnProps, Base.Root.Props {}

/**
 * A task's completion. `value={null}` is indeterminate. With no children it renders a bare
 * track and indicator, so `<Progress.Root value={40} aria-label="Upload" />` is complete.
 */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    tone = 'accent',
    className,
    style,
    children,
    ...rest
  } = withDefaults(config, 'Progress.Root', props);
  const f = fraction(rest.value, rest.min, rest.max);
  return (
    <Base.Root
      {...rest}
      data-tone={tone}
      style={withVars(style, f === null ? undefined : { '--hj-progress-fraction': f })}
      className={cls(config, 'Progress.Root', 'hj-progress', className)}
    >
      {children ?? (
        <Track>
          <Indicator />
        </Track>
      )}
    </Base.Root>
  );
}

/**
 * The fill. Drawn at full width and scaled from the left (transform only — a width
 * animation drops frames), so it rides the clamped snappy spring between values.
 */
export function Indicator(props: Base.Indicator.Props): React.ReactElement {
  const config = useHanjiConfig();
  const { className, style, ...rest } = withDefaults(config, 'Progress.Indicator', props);
  return (
    <Base.Indicator
      {...rest}
      style={withVars(style, FULL_WIDTH)}
      className={cls(config, 'Progress.Indicator', 'hj-progress-indicator', className)}
    />
  );
}

/** Overrides Base UI's inline width: the fill is a full-width element scaled by --hj-progress-fraction. */
const FULL_WIDTH: React.CSSProperties = { width: '100%' };
